parameters.jsCode:
// Читаем русский или английский ключ контента из ответа модели
const choices = $input.item.json.выбор || $input.item.json.choices;
const message = choices[0].сообщение || choices[0].message;
const responseText = message.содержимое || message.content;

try {
  // Пытаемся распарсить JSON, если модель выплюнула его чистым
  return { json: JSON.parse(responseText.trim()) };
} catch (e) {
  // Если модель налила воды вокруг JSON, возвращаем текст как есть
  return { json: { error: "Ответ не является чистым JSON", text: responseText } };
}
